const $=s=>document.querySelector(s);let data=null,metric='views',sortKey='index',sortDesc=false,pin='',busy=false,lockedUntil=0;const labels={views:['每天有多少次访问？','页面打开次数，包含同一浏览器的再次访问。','访问次数'],visitors:['每天有多少个浏览器来过？','每日独立匿名浏览器数；每天去重，不能相加为期间访客。','每日访客'],starts:['每天有多少轮练习开始？','按开始日统计；从不同章节进入、重新练习都会新增一轮。','启动轮次'],completed:['这些练习，有多少已经完成？','按启动日归属的已完成轮次；仅包含所选期间启动的练习。','完成轮次']};const fmt=n=>Number(n).toLocaleString('zh-CN'),pct=(a,b)=>b?`${(100*a/b).toFixed(1)}%`:'暂无';
function dots(){document.querySelectorAll('.pin-dots i').forEach((n,i)=>n.classList.toggle('filled',i<pin.length));$('.pin-dots').setAttribute('aria-label',`已输入 ${pin.length} 位`)}
async function key(k){if(busy||Date.now()<lockedUntil)return;if(k==='clear')pin='';else if(k==='delete')pin=pin.slice(0,-1);else if(/^\d$/.test(k)&&pin.length<6)pin+=k;dots();if(pin.length!==6)return;busy=true;$('#pin-error').textContent='正在验证…';try{const r=await fetch('../api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:pin})});const result=await r.json();if(!r.ok){if(r.status===429)lockedUntil=Date.now()+result.retryAfter*1000;throw Error(result.error||'验证失败')}pin='';dots();await load()}catch(e){$('#pin-error').textContent=e.message==='Failed to fetch'?'暂时无法连接，请重试。':e.message;pin='';dots()}finally{busy=false}}
document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>key(b.dataset.key));document.addEventListener('keydown',e=>{if($('#gate').hidden||e.ctrlKey||e.metaKey||e.altKey)return;let k=e.key;if(k==='Backspace')k='delete';if(k==='Escape')k='clear';if(/^\d$/.test(k)||['delete','clear'].includes(k)){e.preventDefault();key(k)}});setInterval(()=>{if(Date.now()<lockedUntil)$('#pin-error').textContent=`尝试过于频繁，${Math.ceil((lockedUntil-Date.now())/1000)} 秒后重试。`;else if(lockedUntil){lockedUntil=0;$('#pin-error').textContent='可以重新输入访问码。'}},1000);
async function load(){const days=$('#period').value;$('#load-state').textContent='正在读取匿名汇总…';$('#refresh').disabled=true;try{const r=await fetch(`../api/summary?days=${days}`,{cache:'no-store'});if(r.status===401){$('#gate').hidden=false;$('#dashboard').hidden=true;$('#pin-error').textContent='';return}if(!r.ok)throw Error('统计数据暂时无法读取。请重试。');data=await r.json();const opening=$('#dashboard').hidden;$('#load-state').textContent=data.collectedSince&&data.collectedSince.slice(0,10)>data.from?`数据从 ${data.collectedSince.slice(0,10)} 接入，之前日期标为未采集；接入当天为部分数据。`:'';render();if(opening)await window.RefineMotion.switchView($('#gate'),$('#dashboard'))}catch(e){const msg='读取失败，请检查网络后重试。';if($('#dashboard').hidden)$('#pin-error').textContent=msg;else $('#load-state').textContent=data?`${msg} 当前仍显示上次成功读取的范围：${data.from} 至 ${data.to}。`:msg}finally{$('#refresh').disabled=false}}
function render(){const m=data.metrics;$('#scope').textContent=`${data.from} 至 ${data.to} · 上海时区 · 排除 QA 模式`;$('#freshness').textContent=`更新于 ${new Date(data.generatedAt).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}`;const noStart=!m.starts;$('#insight').innerHTML=noStart?`<p>${m.views?`已有 ${fmt(m.visitors)} 个匿名浏览器到访，尚未记录练习启动。`:'还没有访问与练习数据，第一位访客到来后会在这里出现。'}</p><small>从本次埋点接入后开始记录，不回填旧站历史。</small>`:`<p>${fmt(m.starts)} 轮练习中，${fmt(m.completed)} 轮已完成，完成率 ${pct(m.completed,m.starts)}。</p><small>新版每阶独立练习 8 题；旧版按入口剩余题数判断完成。分阶结果见下方。</small>`;const items=[['匿名访客',fmt(m.visitors),'当前浏览器标识去重'],['访问次数',fmt(m.views),'页面打开次数'],['开始练习',fmt(m.starts),'按练习轮次计'],['完成率',pct(m.completed,m.starts),`${fmt(m.completed)} / ${fmt(m.starts)} 轮`],['答题 / 保存笔记',`${fmt(m.answers)} / ${fmt(m.notes)}`,'题目首次提交 / 保存操作']];$('#metrics').innerHTML=items.map(([a,b,c])=>`<div><div class="metric-label">${a}</div><div class="metric-value">${b}</div><div class="metric-detail">${c}</div></div>`).join('');renderQuestionInsight();renderQuestions();const chapterNames={0:'旧版 · 设计基础',4:'旧版 · 场景迁移',6:'旧版 · 全程体验'},newNames={0:'低阶 · 基础设计原则',8:'中阶 · 考虑使用场景',16:'高阶 · 设计取舍与判断',24:'读图 · 读懂画面与故事'};$('#chapters').innerHTML=data.chapters.filter(c=>c.course===Number($('#course-scope').value.split('-')[0])).map(c=>`<tr><td>${c.course===2?newNames[c.start]:chapterNames[c.start]}</td><td>${fmt(c.runs)}</td><td>${fmt(c.completed)}</td><td>${pct(c.completed,c.runs)}</td></tr>`).join('');$('#data-origin').textContent=`腾讯云匿名事件库 · Asia/Shanghai · 最近 ${data.days} 个自然日（含今日）。${data.collectedSince?'当前保留的最早事件：'+new Date(data.collectedSince).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'。':'尚未收到事件。'}仅保留最近 90 天，不提供前期变化对比。`;drawChart()}
function scopedQuestions(){const [version,ch]=$('#course-scope').value.split('-').map(Number);return data.questions.filter(q=>q.course===version&&(version===1||Math.floor(q.index/8)===ch))}
function renderQuestionInsight(){const answered=scopedQuestions().filter(q=>q.answers>0&&q.kind!=='open').sort((a,b)=>a.correct/a.answers-b.correct/b.answers||b.answers-a.answers);if(!answered.length)$('#question-insight').textContent='尚无答题数据。用户提交后，可以观察哪些概念需要进一步讲解。';else{const lowest=answered[0],ratio=lowest.correct/lowest.answers,tied=answered.filter(q=>q.correct/q.answers===ratio),small=lowest.answers<10?'样本不足 10 次，先观察，不急于下结论。':'可优先检查案例是否清楚、讲解是否足够。';$('#question-insight').textContent=tied.length===answered.length?`当前已作答题目的正确率相同，均为 ${pct(lowest.correct,lowest.answers)}，各题样本详见下表。${small}`:`「${lowest.name}」${tied.length>1?'等 '+tied.length+' 个概念并列':''}当前正确率最低，为 ${pct(lowest.correct,lowest.answers)}（该题 ${lowest.correct} / ${lowest.answers} 次）。${small}`}}
function renderQuestions(){if(!data)return;const value=q=>sortKey==='accuracy'?(q.correct!==null&&q.answers?q.correct/q.answers:-1):sortKey==='reach'?(q.eligible?q.answers/q.eligible:-1):q[sortKey];const rows=scopedQuestions().sort((a,b)=>(value(a)-value(b))*(sortDesc?-1:1)||a.index-b.index);$('#questions').innerHTML=rows.map(q=>`<tr><td>${q.course===2?'新版':'旧版'} ${q.index+1}. ${q.name}</td><td>${fmt(q.answers)}</td><td>${q.kind==='open'?'开放表达 · 不评分':pct(q.correct,q.answers)+(q.answers?` (${q.correct}/${q.answers})`:'')}</td><td>${fmt(q.answers)} / ${fmt(q.eligible)}</td></tr>`).join('');document.querySelectorAll('[data-sort]').forEach(b=>b.closest('th').setAttribute('aria-sort',b.dataset.sort===sortKey?(sortDesc?'descending':'ascending'):'none'))}
function drawChart(){if(!data)return;const [title,sub,label]=labels[metric];$('#chart-title').textContent=title;$('#chart-subtitle').textContent=sub;$('#trend-panel').setAttribute('aria-labelledby','tab-'+metric);const rows=data.daily.filter(d=>d.covered),any=rows.some(d=>d[metric]>0);if(!any)$('#chart').innerHTML='<div class="chart-empty">当前范围尚无该指标数据。<br>采集到真实事件后再显示趋势。</div>';else{const W=1000,H=210,left=38,right=20,top=15,bottom=30,max=Math.max(...rows.map(d=>d[metric]),1),x=i=>left+i*(W-left-right)/Math.max(1,rows.length-1),y=v=>H-bottom-v*(H-top-bottom)/max;const ticks=[0,Math.ceil(max/2),max].filter((v,i,a)=>a.indexOf(v)===i);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${data.from} 至 ${data.to} ${label}趋势">`;svg+=ticks.map(v=>`<line x1="${left}" y1="${y(v)}" x2="${W-right}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${v}</text>`).join('');svg+=`<polyline points="${rows.map((d,i)=>`${x(i)},${y(d[metric])}`).join(' ')}"/>`;svg+=rows.map((d,i)=>`<circle cx="${x(i)}" cy="${y(d[metric])}" r="3" tabindex="0" aria-label="${d.day}，${label} ${d[metric]}"><title>${d.day} · ${label} ${d[metric]}</title></circle>`).join('');svg+=`<text x="${left}" y="${H-4}">${rows[0].day.slice(5)}</text><text x="${W-right}" y="${H-4}" text-anchor="end">${rows.at(-1).day.slice(5)}</text></svg>`;$('#chart').innerHTML=svg}$('#daily-table').innerHTML=`<table><thead><tr><th>日期</th><th>${label}</th></tr></thead><tbody>${data.daily.map(d=>`<tr><td>${d.day}</td><td>${d.covered?fmt(d[metric]):'未采集'}</td></tr>`).join('')}</tbody></table>`}
function switchTab(button){metric=button.dataset.metric;document.querySelectorAll('[role=tab]').forEach(b=>{const active=b===button;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});window.RefineMotion.swap($('#trend-panel'),drawChart)}
document.querySelectorAll('[role=tab]').forEach((b,i,all)=>{b.onclick=()=>switchTab(b);b.onkeydown=e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%all.length;else if(e.key==='ArrowLeft')next=(i+all.length-1)%all.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=all.length-1;else return;e.preventDefault();switchTab(all[next]);all[next].focus()}});document.querySelectorAll('[data-sort]').forEach(b=>b.onclick=()=>{if(sortKey===b.dataset.sort)sortDesc=!sortDesc;else{sortKey=b.dataset.sort;sortDesc=true}window.RefineMotion.swap($('#questions'),renderQuestions)});$('.collapse-values').onclick=()=>{window.RefineMotion.toggleDetails($('.chart-values'),false).then(()=>$('.chart-values summary').focus())};$('#period').onchange=load;$('#refresh').onclick=load;$('#course-scope').onchange=render;$('#reset').onclick=()=>{$('#course-scope').value='2-0';$('#period').value='7';sortKey='index';sortDesc=false;switchTab($('#tab-views'));load()};$('#logout').onclick=async()=>{try{const r=await fetch('../api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();data=null;await window.RefineMotion.switchView($('#dashboard'),$('#gate'));$('#pin-error').textContent='已退出。'}catch{$('#load-state').textContent='退出失败，请重试。'}};const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible.length){document.querySelectorAll('.section-nav a').forEach(a=>a.classList.toggle('current',a.hash==='#'+visible[0].target.id))}},{rootMargin:'-65px 0px -45% 0px'});document.querySelectorAll('.dash-section').forEach(s=>observer.observe(s));load();
